-- SQL DDL for ClickHouse, generated by ormbridge.

CREATE TABLE accounts (
  id Int64,
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  deleted_at Nullable(DateTime64(3)),
  email String,
  balance Decimal(10, 2),
  score Nullable(Float64),
  avatar Nullable(String) COMMENT 'binary data',
  payload Nullable(String) COMMENT 'JSON document',
  labels Array(String),
  ttl Nullable(Int64) COMMENT 'duration in microseconds',
  ip Nullable(IPv6),
  homepage_url Nullable(String),
  born Nullable(Date32),
  alarm Nullable(String) COMMENT 'time of day (HH:MM:SS)',
  status Enum8('draft' = 1, 'live' = 2) DEFAULT 'draft',
  note String DEFAULT 'it''s; fine',
  INDEX accounts_deleted_at_idx deleted_at TYPE minmax GRANULARITY 4,
  INDEX accounts_email_status_idx (email, status) TYPE set(100) GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE sessions (
  id UUID DEFAULT generateUUIDv4(),
  token Nullable(UUID) DEFAULT generateUUIDv4(),
  deleted_at Nullable(DateTime64(3)),
  opened_at DateTime64(3) DEFAULT now64(3),
  account_id Nullable(Int64),
  INDEX sessions_account_id_opened_at_idx (account_id, opened_at) TYPE set(100) GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE `groups` (
  id Int32,
  name String
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE memberships (
  role Enum8('owner' = 1, 'member' = 2),
  account_id Int64,
  group_id Int32
)
ENGINE = MergeTree()
ORDER BY (account_id, group_id)
PRIMARY KEY (account_id, group_id);

CREATE TABLE profiles (
  id Int32,
  bio Nullable(String),
  owner_account_id Int64
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE `LEGACY_ORDER` (
  `OrderNo` Int32,
  kind String,
  http_code Int32,
  `first name` Nullable(String),
  acct Nullable(Int64)
)
ENGINE = MergeTree()
ORDER BY (`OrderNo`)
PRIMARY KEY (`OrderNo`);

CREATE TABLE groups_friends (
  id Int32,
  from_group_id Int32,
  to_group_id Int32,
  INDEX groups_friends_from_group_id_to_group_id_idx (from_group_id, to_group_id) TYPE set(100) GRANULARITY 4
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id)
COMMENT 'many-to-many join table';
